package com.example.campsitelottery

import com.google.firebase.firestore.DocumentId
import java.util.Date

/**
 * Documentation generated by Gemini
 * Represents a lottery waitlist listing for one or more campsites.
 * Handles entrant pools, winner selection, and booking time windows.
 *
 * @property waitlistId Firestore document ID for this waitlist listing.
 * @property campsiteIds List of campsite IDs linked to this lottery waitlist.
 * @property ownerId Device/User ID of the owner hosting the lottery.
 * @property lotteryName Descriptive name or title for the lottery draw.
 * @property registrationStartDate Start date of the entrant registration window.
 * @property registrationEndDate End date of the entrant registration window.
 * @property bookingStartDate Start date of the reservation booking window for winners.
 * @property bookingEndDate End date of the reservation booking window for winners.
 * @property numberOfWinnersToDraw Target quota of winners to draw during the lottery execution.
 * @property maxWaitlistCapacity Optional maximum limit on total joined entrants allowed.
 * @property isDrawn Flag indicating whether the automatic winner draw has executed.
 * @property joinedEntrantIds Mutable list of entrant User IDs currently joined in the waitlist pool.
 * @property selectedWinnerIds Mutable list of entrant User IDs selected as winners.
 * @property declinedEntrantIds Mutable list of entrant User IDs who declined their winning invitation.
 */
data class Waitlist(
    @DocumentId
    val waitlistId: String = "",
    var campsiteIds: List<String> = emptyList(),  // Supports single or multi-campsite lotteries
    var ownerId: String = "",
    var lotteryName: String = "",

    // Configurable time windows
    var registrationStartDate: Date? = null,
    var registrationEndDate: Date? = null,
    var bookingStartDate: Date? = null,
    var bookingEndDate: Date? = null,

    // Capacity & Drawing settings
    var numberOfWinnersToDraw: Int = 1,
    var maxWaitlistCapacity: Int? = null, // Optional waitlist capacity limit
    var isDrawn: Boolean = false, // Tracks whether automatic draw has executed

    // Entrant Pools (Tracked by Entrant User IDs)
    var joinedEntrantIds: MutableList<String> = mutableListOf(), // Active waiting list
    var selectedWinnerIds: MutableList<String> = mutableListOf(), // Entrants selected by lottery
    var declinedEntrantIds: MutableList<String> = mutableListOf() // Entrants who declined their win
) {
    /**
     * Documentation generated by Gemini
     * Required no-argument secondary constructor for Firestore deserialization.
     */
    constructor() : this(
        waitlistId = "",
        campsiteIds = emptyList(),
        ownerId = "",
        lotteryName = "",
        registrationStartDate = null,
        registrationEndDate = null,
        bookingStartDate = null,
        bookingEndDate = null,
        numberOfWinnersToDraw = 1,
        maxWaitlistCapacity = null,
        isDrawn = false,
        joinedEntrantIds = mutableListOf(),
        selectedWinnerIds = mutableListOf(),
        declinedEntrantIds = mutableListOf()
    )

    /**
     * Documentation generated by Gemini
     * Helper to check if the waitlist has reached its maximum capacity limit.
     *
     * @return True if [maxWaitlistCapacity] is defined and [joinedEntrantIds] count equals or exceeds it.
     */
    fun isFull(): Boolean {
        val capacity = maxWaitlistCapacity ?: return false
        return joinedEntrantIds.size >= capacity
    }

    /**
     * Documentation generated by Gemini
     * Helper to check if entrant registration is currently open based on current system time.
     *
     * @return True if registration dates are configured, registration window covers current time, and draw has not run.
     */
    fun isRegistrationOpen(): Boolean {
        val now = Date()
        val start = registrationStartDate ?: return false
        val end = registrationEndDate ?: return false
        return !isDrawn && now.after(start) && now.before(end)
    }
}